"""Generate the public tool reference from the actual registration and methods."""

import argparse
import inspect
from pathlib import Path

from tvheadend_mcp.admin import TvheadendAdmin
from tvheadend_mcp.server import READ_TOOLS, WRITE_TOOLS

TARGET = Path(__file__).resolve().parents[1] / "docs" / "tools.md"


def render() -> str:
    lines = [
        "# Tool reference",
        "",
        "Generated from the registered Python methods. Do not edit this file by hand.",
        "Run `uv run python scripts/generate_tool_reference.py` after tool changes.",
        "",
        f"{len(READ_TOOLS)} read tools and {len(WRITE_TOOLS)} write tools are registered.",
        "Write tools accept `dry_run`; normal calls execute unless documented otherwise.",
        "`TVH_READ_ONLY=true` blocks writes while permitting reads and previews.",
        "UUIDs, class names, field IDs and options must come from the connected server.",
        "",
    ]
    for name in sorted(READ_TOOLS | WRITE_TOOLS):
        method = getattr(TvheadendAdmin, name)
        signature = inspect.signature(method)
        signature = signature.replace(
            parameters=[p for key, p in signature.parameters.items() if key != "self"]
        )
        kind = "Read" if name in READ_TOOLS else "Write"
        lines.extend(
            [
                f"## `tvh_{name}`",
                "",
                f"**{kind}.**",
                "",
                "```python",
                f"tvh_{name}{signature}",
                "```",
                "",
                inspect.getdoc(method) or "",
                "",
            ]
        )
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the reference is stale")
    args = parser.parse_args()
    expected = render()
    if args.check:
        if not TARGET.is_file() or TARGET.read_text() != expected:
            raise SystemExit("Tool reference is stale; run scripts/generate_tool_reference.py")
        print("Tool reference is current.")
    else:
        TARGET.write_text(expected)
        print(f"Wrote {TARGET.name} with {len(READ_TOOLS | WRITE_TOOLS)} tools.")


if __name__ == "__main__":
    main()
